import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import DashboardCharts from "../components/charts/DashboardCharts";

function AdminDashboard() {

    const navigate = useNavigate();

    const [bookings, setBookings] = useState([]);

    const [dashboardData, setDashboardData] =
        useState({});

    const [searchText, setSearchText] =
        useState("");


    // ==========================================
    // LOAD DATA
    // ==========================================

    useEffect(() => {

        fetchBookings();
        fetchDashboardData();

    }, []);


    // ==========================================
    // FETCH BOOKINGS
    // ==========================================

    const fetchBookings = () => {

        axios
            .get(
                "http://localhost:8081/booking/all"
            )
            .then((response) => {

                setBookings(
                    response.data
                );

            })
            .catch((error) => {

                console.error(
                    "Booking Error:",
                    error
                );

            });

    };


    // ==========================================
    // FETCH DASHBOARD DATA
    // ==========================================

    const fetchDashboardData = () => {

        axios
            .get(
                "http://localhost:8081/admin/dashboard"
            )
            .then((response) => {

                setDashboardData(
                    response.data
                );

            })
            .catch((error) => {

                console.error(
                    "Dashboard Error:",
                    error
                );

            });

    };


    // ==========================================
    // APPROVE BOOKING
    // ==========================================

    const approveBooking = (id) => {

        axios
            .put(
                `http://localhost:8081/booking/approve/${id}`
            )
            .then(() => {

                alert(
                    "Booking Approved"
                );

                fetchBookings();

                fetchDashboardData();

            })
            .catch((error) => {

                console.error(
                    "Approve Error:",
                    error
                );

            });

    };


    // ==========================================
    // REJECT BOOKING
    // ==========================================

    const rejectBooking = (id) => {

        axios
            .put(
                `http://localhost:8081/booking/reject/${id}`
            )
            .then(() => {

                alert(
                    "Booking Rejected"
                );

                fetchBookings();

                fetchDashboardData();

            })
            .catch((error) => {

                console.error(
                    "Reject Error:",
                    error
                );

            });

    };


    // ==========================================
    // FILTER BOOKINGS
    // ==========================================

    const filteredBookings =
        bookings.filter((booking) => {

            if (
                !booking.customer ||
                !booking.customer.name
            ) {
                return false;
            }

            return booking.customer.name
                .toLowerCase()
                .includes(
                    searchText.toLowerCase()
                );

        });


    // ==========================================
    // RETURN
    // ==========================================

    return (

        <div
            style={{
                padding: "30px",
                width: "100%",
                boxSizing: "border-box"
            }}
        >

            {/* ==========================================
                PAGE TITLE
            ========================================== */}

            <h1
                style={{
                    marginTop: "0",
                    marginBottom: "20px"
                }}
            >
                Admin Dashboard
            </h1>


            {/* ==========================================
                ACTION BUTTONS
            ========================================== */}

            <div
                style={{
                    display: "flex",
                    gap: "15px",
                    marginBottom: "25px",
                    flexWrap: "wrap"
                }}
            >

                <button
                    onClick={() =>
                        navigate(
                            "/manage-cars"
                        )
                    }
                    style={{
                        backgroundColor: "black",
                        color: "white",
                        border: "none",
                        padding: "12px 20px",
                        borderRadius: "5px",
                        cursor: "pointer"
                    }}
                >
                    🚗 Manage Cars
                </button>


                <button
                    onClick={() =>
                        navigate(
                            "/manage-reviews"
                        )
                    }
                    style={{
                        backgroundColor: "#ff9800",
                        color: "white",
                        border: "none",
                        padding: "12px 20px",
                        borderRadius: "5px",
                        cursor: "pointer"
                    }}
                >
                    Manage Reviews
                </button>

            </div>


            {/* ==========================================
                SEARCH
            ========================================== */}

            <input
                type="text"
                placeholder="Search By Customer Name"
                value={searchText}
                onChange={(e) =>
                    setSearchText(
                        e.target.value
                    )
                }
                style={{
                    padding: "12px",
                    width: "300px",
                    maxWidth: "100%",
                    borderRadius: "5px",
                    border: "1px solid gray",
                    boxSizing: "border-box"
                }}
            />


            {/* ==========================================
                STATISTICS CARDS
                ONE SINGLE ROW ON DESKTOP
            ========================================== */}

            <div
                style={{
                    display: "grid",

                    /*
                     * Four cards always share
                     * the same row on desktop.
                     */
                    gridTemplateColumns:
                        "repeat(4, minmax(0, 1fr))",

                    gap: "15px",

                    width: "100%",

                    marginTop: "25px",

                    marginBottom: "20px",

                    boxSizing: "border-box"
                }}
            >

                {/* CUSTOMERS */}

                <div
                    style={{
                        backgroundColor: "#f1f1f1",

                        padding:
                            "14px 18px",

                        height: "90px",

                        borderRadius: "8px",

                        border:
                            "1px solid #e5e5e5",

                        boxSizing:
                            "border-box",

                        display: "flex",

                        flexDirection:
                            "column",

                        justifyContent:
                            "center"
                    }}
                >

                    <h3
                        style={{
                            margin: "0 0 5px 0",
                            fontSize: "18px"
                        }}
                    >
                        Customers
                    </h3>

                    <h2
                        style={{
                            margin: "0",
                            fontSize: "28px"
                        }}
                    >
                        {
                            dashboardData
                                .totalCustomers
                        }
                    </h2>

                </div>


                {/* CARS */}

                <div
                    style={{
                        backgroundColor: "#f1f1f1",

                        padding:
                            "14px 18px",

                        height: "90px",

                        borderRadius: "8px",

                        border:
                            "1px solid #e5e5e5",

                        boxSizing:
                            "border-box",

                        display: "flex",

                        flexDirection:
                            "column",

                        justifyContent:
                            "center"
                    }}
                >

                    <h3
                        style={{
                            margin: "0 0 5px 0",
                            fontSize: "18px"
                        }}
                    >
                        Cars
                    </h3>

                    <h2
                        style={{
                            margin: "0",
                            fontSize: "28px"
                        }}
                    >
                        {
                            dashboardData
                                .totalCars
                        }
                    </h2>

                </div>


                {/* BOOKINGS */}

                <div
                    style={{
                        backgroundColor: "#f1f1f1",

                        padding:
                            "14px 18px",

                        height: "90px",

                        borderRadius: "8px",

                        border:
                            "1px solid #e5e5e5",

                        boxSizing:
                            "border-box",

                        display: "flex",

                        flexDirection:
                            "column",

                        justifyContent:
                            "center"
                    }}
                >

                    <h3
                        style={{
                            margin: "0 0 5px 0",
                            fontSize: "18px"
                        }}
                    >
                        Bookings
                    </h3>

                    <h2
                        style={{
                            margin: "0",
                            fontSize: "28px"
                        }}
                    >
                        {
                            dashboardData
                                .totalBookings
                        }
                    </h2>

                </div>


                {/* PAYMENTS */}

                <div
                    style={{
                        backgroundColor: "#f1f1f1",

                        padding:
                            "14px 18px",

                        height: "90px",

                        borderRadius: "8px",

                        border:
                            "1px solid #e5e5e5",

                        boxSizing:
                            "border-box",

                        display: "flex",

                        flexDirection:
                            "column",

                        justifyContent:
                            "center"
                    }}
                >

                    <h3
                        style={{
                            margin: "0 0 5px 0",
                            fontSize: "18px"
                        }}
                    >
                        Payments
                    </h3>

                    <h2
                        style={{
                            margin: "0",
                            fontSize: "28px"
                        }}
                    >
                        {
                            dashboardData
                                .totalPayments
                        }
                    </h2>

                </div>

            </div>


            {/* ==========================================
                CHART SECTION
                CONTROLLED HEIGHT
                PREVENTS OVERLAP WITH BOOKINGS
            ========================================== */}

            <div
                style={{
                    width: "100%",

                    height: "400px",

                    overflow: "hidden",

                    position: "relative",

                    marginBottom: "20px",

                    boxSizing: "border-box"
                }}
            >

                <div
                    style={{
                        width: "100%",

                        height: "100%",

                        display: "flex",

                        justifyContent:
                            "center",

                        alignItems:
                            "flex-start",

                        overflow: "hidden"
                    }}
                >

                    <div
                        style={{
                            width: "100%",

                            maxWidth: "1100px",

                            transform:
                                "scale(0.90)",

                            transformOrigin:
                                "center top",

                            boxSizing:
                                "border-box"
                        }}
                    >

                        <DashboardCharts
                            dashboardData={
                                dashboardData
                            }
                        />

                    </div>

                </div>

            </div>


            {/* ==========================================
                BOOKING MANAGEMENT
            ========================================== */}

            <div
                style={{
                    marginTop: "10px"
                }}
            >

                <h2
                    style={{
                        marginBottom: "15px"
                    }}
                >
                    Booking Management
                </h2>


                {
                    filteredBookings.length === 0 ? (

                        <div
                            style={{
                                padding: "20px",
                                border:
                                    "1px solid #ddd",
                                borderRadius: "8px",
                                backgroundColor:
                                    "#fafafa"
                            }}
                        >
                            No bookings found.
                        </div>

                    ) : (

                        filteredBookings.map(
                            (booking) => (

                                <div
                                    key={
                                        booking.id
                                    }
                                    style={{
                                        border:
                                            "1px solid lightgray",

                                        padding:
                                            "15px",

                                        marginBottom:
                                            "15px",

                                        borderRadius:
                                            "10px",

                                        backgroundColor:
                                            "white",

                                        boxSizing:
                                            "border-box"
                                    }}
                                >

                                    {/* CAR */}

                                    <h2
                                        style={{
                                            marginTop:
                                                "0",

                                            marginBottom:
                                                "10px"
                                        }}
                                    >
                                        {
                                            booking
                                                .carVariant
                                                ?.variantName
                                        }
                                    </h2>


                                    {/* CUSTOMER */}

                                    <p
                                        style={{
                                            margin:
                                                "6px 0"
                                        }}
                                    >

                                        <b>
                                            Customer:
                                        </b>

                                        {" "}

                                        {
                                            booking.customer
                                                ? booking
                                                    .customer
                                                    .name
                                                : "No Customer"
                                        }

                                    </p>


                                    {/* TOTAL */}

                                    <p
                                        style={{
                                            margin:
                                                "6px 0"
                                        }}
                                    >

                                        <b>
                                            Total Amount:
                                        </b>

                                        {" "}

                                        ₹
                                        {" "}
                                        {
                                            booking.totalAmount
                                        }

                                    </p>


                                    {/* STATUS */}

                                    <p
                                        style={{
                                            margin:
                                                "6px 0"
                                        }}
                                    >

                                        <b>
                                            Status:
                                        </b>

                                        {" "}

                                        <span
                                            style={{
                                                color:
                                                    booking
                                                        .bookingStatus
                                                        ===
                                                        "APPROVED"

                                                        ? "green"

                                                        :

                                                        booking
                                                            .bookingStatus
                                                            ===
                                                            "REJECTED"

                                                            ? "red"

                                                            : "orange",

                                                fontWeight:
                                                    "bold"
                                            }}
                                        >
                                            {
                                                booking
                                                    .bookingStatus
                                            }
                                        </span>

                                    </p>


                                    {/* BUTTONS */}

                                    <div
                                        style={{
                                            display:
                                                "flex",

                                            gap:
                                                "10px",

                                            marginTop:
                                                "12px"
                                        }}
                                    >

                                        <button
                                            onClick={() =>
                                                approveBooking(
                                                    booking.id
                                                )
                                            }
                                            style={{
                                                backgroundColor:
                                                    "green",

                                                color:
                                                    "white",

                                                border:
                                                    "none",

                                                padding:
                                                    "9px 16px",

                                                borderRadius:
                                                    "5px",

                                                cursor:
                                                    "pointer"
                                            }}
                                        >
                                            Approve
                                        </button>


                                        <button
                                            onClick={() =>
                                                rejectBooking(
                                                    booking.id
                                                )
                                            }
                                            style={{
                                                backgroundColor:
                                                    "red",

                                                color:
                                                    "white",

                                                border:
                                                    "none",

                                                padding:
                                                    "9px 16px",

                                                borderRadius:
                                                    "5px",

                                                cursor:
                                                    "pointer"
                                            }}
                                        >
                                            Reject
                                        </button>

                                    </div>

                                </div>

                            )
                        )

                    )

                }

            </div>

        </div>

    );

}

export default AdminDashboard;
